# region: render
def render(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: shape
def shape(xs):
    return [v * v for v in xs]

# region: sift
def sift(xs, limit=5):
    return [v if v <= limit else limit for v in xs]

# region: fold
def fold(xs):
    return {'n': len(xs) - 1, 'total': sum(xs)}

# region: gather
def gather(summary, bar=2):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return gather(fold(sift(shape(render(raw)))))

